import unittest

from refunds import refund_mode


class RefundModeTest(unittest.TestCase):
    def test_fast_refunds_are_off_by_default(self):
        self.assertEqual("standard", refund_mode({}))

    def test_fast_refunds_can_be_enabled(self):
        self.assertEqual("fast", refund_mode({"FAST_REFUNDS": "true"}))


if __name__ == "__main__":
    unittest.main()
